/** First award month graded across MLB and NFL together (David 2026-10-02).
 * Earlier months were MLB-only and their straights cards say so. */
export const COMBINED_SPORTS_FROM = "2026-09";

/** Card/page headline for an award. Straights awards before
 * COMBINED_SPORTS_FROM keep "MLB Capper" (those cards are already posted);
 * from then on the board spans both sports, so the sport drops out. */
export function awardHeadline(award: Pick<MonthlyAward, "category" | "month">): string {
  if (award.category === "straights" && award.month >= COMBINED_SPORTS_FROM) {
    return "Straight Bet Capper";
  }
  return AWARD_CATEGORIES[award.category].headline;
}

export function getAward(slug: string): MonthlyAward | null {
  return MONTHLY_AWARDS.find((a) => a.slug === slug) ?? null;
}

/** Month range for the verify link, e.g. { start: "2026-06-01", end: "2026-06-30" }. */
export function awardMonthRange(award: MonthlyAward): { start: string; end: string } {
  const [y, m] = award.month.split("-").map(Number);
  const lastDay = new Date(Date.UTC(y, m, 0)).getUTCDate();
  const mm = String(m).padStart(2, "0");
  return { start: `${award.month}-01`, end: `${y}-${mm}-${String(lastDay).padStart(2, "0")}` };
}

export function awardVerifyHref(award: MonthlyAward): string {
  const range = awardMonthRange(award);
  const params = new URLSearchParams({
    start: range.start,
    end: range.end,
    ...AWARD_CATEGORIES[award.category].verifyParams,
  });
  return `/cappers/${award.handle}?${params.toString()}`;
}
